import itertools
t=df['t'];P=df['P'];y=df['dP_dt']
base=np.column_stack([t,P*np.log(P),np.log(1+t)**2/P])
def fit(f):
    B=np.column_stack([base,f]); cc=np.linalg.lstsq(B,y,rcond=None)[0]
    return np.mean((y-B@cc)**2)/np.var(y)
gcands={}
for a in [0.5,1,1.5,2]: gcands[f'P^-{a}']=P**-a
for k in [0.5,1,2,3]: gcands[f'exp(-{k}P)']=np.exp(-k*P)
for k in [0.5,1,2]: gcands[f'1/(P+{k})']=1/(P+k)
gcands['1']=P*0+1
for c in [1,2,3,5]: gcands[f'1/(1+P/{c})']=1/(1+P/c)
hc={}
for k in [1,2,3,4,5,6,8,10]:
    hc[f't e^-t/{k}']=t*np.exp(-t/k)
    hc[f'log1p e^-t/{k}']=np.log(1+t)*np.exp(-t/k)
    hc[f'log t e^-t/{k}']=np.log(t)*np.exp(-t/k)
for m in np.arange(1,12,0.5):
    for s in [1,2,3,4,6]:
        hc[f'gauss m{m} s{s}']=np.exp(-(t-m)**2/(2*s*s))
for w in np.arange(0.1,1.6,0.05):
    for ph in np.arange(0,2*np.pi,np.pi/8):
        hc[f'sin w{w:.2f} ph{ph:.2f}']=np.sin(w*t+ph)
res=[]
for hn,h in hc.items():
    for gn,g in gcands.items():
        res.append((fit(h*g),hn,gn))
res.sort()
